258	    @Override
259	    @Transactional
260	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
261	        rejectWhenDailyLimitReached(owner);
262	        rejectWhenCityAtCapacity(owner);
263	        owner.setHouseholdId(deriveHouseholdId(owner));
264	        List<Owner> householdMembers = findHouseholdMembers(owner);
265	        rejectWhenHouseholdDuplicate(owner, householdMembers, sharesHousehold);
266	        assignPossibleDuplicate(owner);
267	        owner.setHouseholdMemberCount(householdMembers.size() + 1);
268	        if (owner.getCustomerCode() == null) {
269	            owner.setCustomerCode(deduplicateCustomerCode(deriveCustomerCode(owner)));
270	        }
271	        if (owner.getNamesakeCount() == null) {
272	            owner.setNamesakeCount(countNamesakes(owner));
273	        }
274	        owner.setBulkSignupWarning(exceedsBulkSignupThreshold(owner));
275	        ownerRepository.save(owner);
276	    }
277	
278	    /** Number of owners created on a single day beyond which the bulk-signup warning is raised. */
279	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
280	
281	    /**
282	     * Whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created
283	     * today (compared by {@code registrationDate}), evaluated before this owner is persisted so it
284	     * reflects the owners present at creation time. The new owner's registration date, defaulted to
285	     * today by the controller, determines which day is counted — the same accumulation path as the
286	     * daily-limit rule.
287	     */
288	    private boolean exceedsBulkSignupThreshold(Owner owner) {
289	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
290	        return countOwnersRegisteredOn(day) > BULK_SIGNUP_WARNING_THRESHOLD;
291	    }
292	
293	    /**
294	     * Count the existing owners that already share this owner's first name and last name,
295	     * compared case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated
296	     * before the owner is persisted, so it reflects the owners present at creation time.
297	     */
298	    private int countNamesakes(Owner owner) {
299	        String firstName = IdentityNormalizer.normalize(owner.getFirstName());
300	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
301	        return (int) findActiveOwners().stream()
302	            .filter(existing -> firstName.equals(IdentityNormalizer.normalize(existing.getFirstName()))
303	                && lastName.equals(IdentityNormalizer.normalize(existing.getLastName())))
304	            .count();
305	    }
306	
307	    /**
308	     * The existing owners that have not been soft-deleted. Duplicate and identity checks run
309	     * against this set, so an owner flagged {@code deleted} (see {@link #deleteOwner(Owner)}) is
310	     * ignored and no longer blocks a create that would otherwise match it.
311	     */
312	    private List<Owner> findActiveOwners() {
313	        return ownerRepository.findAll().stream()
314	            .filter(existing -> !existing.isDeleted())
315	            .toList();
316	    }
317	
318	    /**
319	     * The existing owners that already belong to this owner's household, i.e. those carrying the
320	     * same deterministic {@code householdId} (see {@link #deriveHouseholdId(Owner)}). Because the
321	     * household id is derived purely from the normalized last name and postcode, this is exactly
322	     * the set of owners sharing that last name and postcode. Evaluated before the owner is
323	     * persisted, so it reflects the owners present at creation time. The owner's own
324	     * {@code householdId} must already be assigned before calling.
325	     */
326	    private List<Owner> findHouseholdMembers(Owner owner) {
327	        String householdId = owner.getHouseholdId();
328	        return findActiveOwners().stream()
329	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
330	            .toList();
331	    }
332	
333	    /**
334	     * Derive the owner's deterministic household identifier: the first twelve hexadecimal characters
335	     * of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two owners with the
336	     * same last name (compared case-insensitively with collapsed whitespace) and postcode therefore
337	     * map to the same value automatically, without any opt-in, so they form one household.
338	     */
339	    private static String deriveHouseholdId(Owner owner) {
340	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
341	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
342	        return sha256HexPrefix(lastName + "|" + postcode, 12);
343	    }
344	
345	    /**
346	     * Reject the create when another owner already belongs to this owner's household (same
347	     * deterministic {@code householdId}, i.e. the same last name and postcode) as a
348	     * {@code 409 Conflict}. The single exception to the block is {@code sharesHousehold}: when set
349	     * the new owner is accepted as a declared member of the existing household rather than rejected.
350	     * Evaluated after the household id has been assigned and before the owner is persisted, so it
351	     * reflects the owners present at creation time.
352	     */
353	    private void rejectWhenHouseholdDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
354	        if (!householdMembers.isEmpty() && !sharesHousehold) {
355	            throw new DuplicateIdentityException(
356	                "an owner already exists in household " + owner.getHouseholdId());
357	        }
358	    }
359	
360	    /**
361	     * Set the new owner's soft-duplicate flags. A declared member of an existing household (reached
362	     * only via {@code sharesHousehold}) is explicitly not a suspected duplicate, and an owner that
363	     * is the first in its household has nothing to be a duplicate of; any other case would already
364	     * have been rejected as a household duplicate. The flags are therefore always cleared here, but
365	     * set explicitly so the field is always present in the response. Evaluated after the
366	     * household-duplicate check and before the owner is persisted.
367	     */
368	    private void assignPossibleDuplicate(Owner owner) {
369	        owner.setPossibleDuplicate(false);
370	        owner.setPossibleDuplicateOf(null);
371	    }
372	
373	    /** Maximum number of owners that may be created on any single day (by registration date). */
374	    private static final long DAILY_OWNER_LIMIT = 100L;
375	
376	    /**
377	     * Reject the create when {@value #DAILY_OWNER_LIMIT} or more owners have already been created
378	     * today (compared by {@code registrationDate}). Evaluated before the owner is persisted, so it
379	     * reflects the owners present at creation time. The new owner's own registration date, defaulted
380	     * to today by the controller, determines which day the limit is checked against.
381	     */
382	    private void rejectWhenDailyLimitReached(Owner owner) {
383	        LocalDate day = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
384	        if (countOwnersRegisteredOn(day) >= DAILY_OWNER_LIMIT) {
385	            throw new DailyOwnerLimitExceededException(
386	                DAILY_OWNER_LIMIT + " or more owners have already been created on " + day);
387	        }
388	    }
389	
390	    /**
391	     * Count the existing owners whose {@code registrationDate} equals the given day. Evaluated
392	     * before the owner is persisted, so it reflects the owners present at creation time.
393	     */
394	    private long countOwnersRegisteredOn(LocalDate day) {
395	        return ownerRepository.findAll().stream()
396	            .filter(existing -> day.equals(existing.getRegistrationDate()))
397	            .count();
398	    }
399	
400	    /** Maximum number of owners allowed to live in any single city. */
401	    private static final long CITY_CAPACITY = 50L;
402	
403	    /**
404	     * Reject the create when the owner's city already contains {@value #CITY_CAPACITY} or more
405	     * owners (compared case-insensitively with collapsed whitespace). Evaluated before the owner
406	     * is persisted, so it reflects the owners present at creation time.
407	     */
408	    private void rejectWhenCityAtCapacity(Owner owner) {
409	        if (countOwnersInCity(owner) >= CITY_CAPACITY) {
410	            throw new CityCapacityExceededException(
411	                "city " + owner.getCity() + " already contains " + CITY_CAPACITY + " or more owners");
412	        }
413	    }
414	
415	    /**
416	     * Count the existing owners that already live in this owner's city, compared
417	     * case-insensitively (with surrounding/collapsed whitespace ignored). Evaluated before the
418	     * owner is persisted, so it reflects the owners present at creation time.
419	     */
420	    private long countOwnersInCity(Owner owner) {
421	        String city = IdentityNormalizer.normalize(owner.getCity());
422	        return ownerRepository.findAll().stream()
423	            .filter(existing -> city.equals(IdentityNormalizer.normalize(existing.getCity())))
424	            .count();
425	    }
426	
427	    /** Region-to-inclusive 4-digit postcode range {@code {low, high}}. */
428	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
429	        "NSW", new int[] {2000, 2099},
430	        "VIC", new int[] {3000, 3099},
431	        "QLD", new int[] {4000, 4099});
432	
433	    /** Region code used when the postcode maps to no known region (or is absent). */
434	    private static final String UNKNOWN_REGION = "UNKNOWN";
435	
436	    /**
437	     * Builds the customer code {@code '<REGION>-<HASH8>'}: the region code derived from the
438	     * owner's postcode, a hyphen, and the first eight upper-case hexadecimal characters of the
439	     * SHA-256 digest over the owner's normalized (E.164) telephone concatenated with the last
440	     * name. No sequence number is used; the identity is fully derived from the region and hash.
441	     */
442	    private String deriveCustomerCode(Owner owner) {
443	        String region = regionForPostcode(owner.getPostcode());
444	        String telephone = TelephoneNormalizer.toComparable(owner.getTelephone());
445	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
446	        return region + "-" + sha256Hex8(telephone + lastName);
447	    }
448	
449	    /**
450	     * De-duplicates a computed {@code customerCode} against the existing owners: if no owner already
451	     * carries {@code baseCode} it is returned unchanged, otherwise {@code '-<n>'} is appended with the
452	     * smallest {@code n} of 2 or more that yields a value no existing owner holds. Evaluated before the
453	     * owner is persisted, so it reflects the owners present at creation time.
454	     */
455	    private String deduplicateCustomerCode(String baseCode) {
456	        Set<String> existingCodes = findActiveOwners().stream()
457	            .map(Owner::getCustomerCode)
458	            .filter(Objects::nonNull)
459	            .collect(Collectors.toSet());
460	        if (!existingCodes.contains(baseCode)) {
461	            return baseCode;
462	        }
463	        int n = 2;
464	        while (existingCodes.contains(baseCode + "-" + n)) {
465	            n++;
466	        }
467	        return baseCode + "-" + n;
468	    }
469	
470	    /**
471	     * Returns the region code whose inclusive postcode range contains {@code postcode}
472	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), or
473	     * {@code "UNKNOWN"} when the postcode is absent, not a 4-digit value, or in no known range.
474	     */
475	    private static String regionForPostcode(String postcode) {
476	        if (postcode == null || !postcode.matches("\\d{4}")) {
477	            return UNKNOWN_REGION;
478	        }
479	        int value = Integer.parseInt(postcode);
480	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
481	            int[] range = entry.getValue();
482	            if (value >= range[0] && value <= range[1]) {
483	                return entry.getKey();
484	            }
485	        }
486	        return UNKNOWN_REGION;
487	    }
488	
489	    /**
490	     * Returns the first eight upper-case hexadecimal characters (the first four bytes) of the
491	     * SHA-256 digest of the UTF-8 bytes of {@code value}.
492	     */
493	    private static String sha256Hex8(String value) {
494	        return sha256HexPrefix(value, 8).toUpperCase();
495	    }
496	
497	    /**
498	     * Returns the first {@code hexChars} lower-case hexadecimal characters of the SHA-256 digest of
499	     * the UTF-8 bytes of {@code value}.
500	     */
501	    private static String sha256HexPrefix(String value, int hexChars) {
502	        try {
503	            byte[] digest = MessageDigest.getInstance("SHA-256")
504	                .digest(value.getBytes(StandardCharsets.UTF_8));
505	            StringBuilder sb = new StringBuilder(hexChars);
506	            for (int i = 0; sb.length() < hexChars; i++) {
507	                sb.append(String.format("%02x", digest[i]));
508	            }
509	            return sb.substring(0, hexChars);
510	        }
511	        catch (NoSuchAlgorithmException e) {
512	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
513	        }
514	    }
515	
