17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Map;
20	
21	/**
22	 * Utility for normalizing telephone numbers into
23	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
24	 *
25	 * <p>Spaces, dashes and brackets are stripped. When the value already carries a
26	 * leading {@code '+'} the country code is kept as supplied; otherwise the country
27	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
28	 * national digits. The result must contain between 8 and 15 digits after the
29	 * {@code '+'}; anything else raises an {@link InvalidTelephoneException} so the
30	 * request is rejected with {@code 400 Bad Request}. For example {@code '0412 345 678'}
31	 * becomes {@code '+61412345678'}.
32	 *
33	 * <p>In addition, for recognized country codes the national number (the digits after
34	 * the country code) must be exactly the length that country uses: {@code '+61'}
35	 * (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10. A number
36	 * whose national-number length does not match its country code is rejected.
37	 */
38	public final class TelephoneNormalizer {
39	
40	    private static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    private static final int MIN_DIGITS = 8;
43	
44	    private static final int MAX_DIGITS = 15;
45	
46	    /**
47	     * Known country calling codes mapped to the exact number of national digits that
48	     * must follow them in a valid E.164 number. Codes not listed here fall back to the
49	     * generic {@link #MIN_DIGITS}-to-{@link #MAX_DIGITS} bound only.
50	     */
51	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = Map.of(
52	        "61", 9,
53	        "1", 10);
54	
55	    private TelephoneNormalizer() {
56	    }
57	
58	    /**
59	     * Normalize the supplied telephone into E.164 form.
60	     *
61	     * @param telephone the raw telephone value (may be {@code null})
62	     * @return the normalized E.164 telephone (a leading {@code '+'} followed by digits)
63	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
64	     */
65	    public static String normalize(String telephone) {
66	        String e164 = toE164(telephone);
67	        if (e164 == null) {
68	            throw new InvalidTelephoneException(
69	                "telephone must be a valid E.164 number (8 to 15 digits after the '+', "
70	                    + "with a national-number length matching its country code: "
71	                    + "'+61' requires 9 national digits, '+1' requires 10)");
72	        }
73	        return e164;
74	    }
75	
76	    /**
77	     * Best-effort conversion of the supplied telephone into E.164 form, returning
78	     * {@code null} instead of throwing when the value cannot form a valid E.164 number.
79	     * Useful for comparing telephones that may already be stored in a non-normalized form.
80	     *
81	     * @param telephone the raw telephone value (may be {@code null})
82	     * @return the E.164 telephone, or {@code null} if it cannot be formed
83	     */
84	    public static String toE164(String telephone) {
85	        if (telephone == null) {
86	            return null;
87	        }
88	        String cleaned = telephone.replaceAll("[\\s\\-()\\[\\]]", "");
89	        String digits;
90	        if (cleaned.startsWith("+")) {
91	            digits = cleaned.substring(1);
92	        }
93	        else {
94	            String national = cleaned;
95	            if (national.startsWith("0")) {
96	                national = national.substring(1);
97	            }
98	            digits = DEFAULT_COUNTRY_CODE + national;
99	        }
100	        if (!digits.matches("\\d+")) {
101	            return null;
102	        }
103	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
104	            return null;
105	        }
106	        if (!hasValidNationalLength(digits)) {
107	            return null;
108	        }
109	        return "+" + digits;
110	    }
111	
112	    /**
113	     * Canonicalize the supplied telephone for equality comparison: its {@link #toE164 E.164} form
114	     * when it can be normalized, otherwise the raw value unchanged, or an empty string when
115	     * {@code null}. Unlike {@link #normalize} this never throws, so callers that compare telephones
116	     * (identity keys, soft-duplicate matching, derived customer codes) treat non-normalizable values
117	     * consistently rather than rejecting them.
118	     *
119	     * @param telephone the raw telephone value (may be {@code null})
120	     * @return the E.164 form, else the raw value, else an empty string
121	     */
122	    public static String toComparable(String telephone) {
123	        String e164 = toE164(telephone);
124	        if (e164 != null) {
125	            return e164;
126	        }
127	        return telephone == null ? "" : telephone;
128	    }
129	
130	    /**
131	     * Format the supplied telephone for human display: the country code, a space, and the
132	     * national digits (the digits after the country code) grouped in threes separated by
133	     * spaces, e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw stored
134	     * telephone stays in E.164 form; this is a read-only presentation of it.
135	     *
136	     * <p>Values that cannot be read as an E.164 number are returned unchanged. When the
137	     * country code is not recognized the whole number is grouped from the leading digit.
138	     *
139	     * @param telephone the stored telephone value (may be {@code null})
140	     * @return the display form, or {@code null} when {@code telephone} is {@code null}
141	     */
142	    public static String toDisplay(String telephone) {
143	        if (telephone == null) {
144	            return null;
145	        }
146	        String e164 = telephone.startsWith("+") ? telephone : toE164(telephone);
147	        if (e164 == null || !e164.startsWith("+")) {
148	            return telephone;
149	        }
150	        String digits = e164.substring(1);
151	        if (!digits.matches("\\d+")) {
152	            return telephone;
153	        }
154	        String countryCode = matchLongestCountryCode(digits);
155	        StringBuilder sb = new StringBuilder("+");
156	        String national;
157	        if (countryCode != null) {
158	            sb.append(countryCode);
159	            national = digits.substring(countryCode.length());
160	        }
161	        else {
162	            national = digits;
163	        }
164	        for (int i = 0; i < national.length(); i += 3) {
165	            if (sb.length() > 1) {
166	                sb.append(' ');
167	            }
168	            sb.append(national, i, Math.min(i + 3, national.length()));
169	        }
170	        return sb.toString();
171	    }
172	
173	    /**
174	     * Check the national-number length of the supplied all-digit E.164 body against its
175	     * country code. The longest matching known country code wins; when the code is
176	     * recognized the remaining (national) digits must be exactly the required length.
177	     * Numbers whose country code is not recognized pass this check (only the generic
178	     * digit-count bound applies to them).
179	     *
180	     * @param digits the E.164 digits (country code plus national number, no {@code '+'})
181	     * @return {@code true} if the national-number length is acceptable for the country code
182	     */
183	    private static boolean hasValidNationalLength(String digits) {
184	        String matchedCode = matchLongestCountryCode(digits);
185	        if (matchedCode == null) {
186	            return true;
187	        }
188	        int nationalLength = digits.length() - matchedCode.length();
189	        return nationalLength == NATIONAL_DIGITS_BY_COUNTRY_CODE.get(matchedCode);
190	    }
191	
192	    /**
193	     * Return the longest known country calling code that prefixes the supplied E.164 digits,
194	     * or {@code null} when none is recognized.
195	     *
196	     * @param digits the E.164 digits (country code plus national number, no {@code '+'})
197	     * @return the matching country code, or {@code null}
198	     */
199	    private static String matchLongestCountryCode(String digits) {
200	        String matchedCode = null;
201	        for (String code : NATIONAL_DIGITS_BY_COUNTRY_CODE.keySet()) {
202	            if (digits.startsWith(code)
203	                && (matchedCode == null || code.length() > matchedCode.length())) {
204	                matchedCode = code;
205	            }
206	        }
207	        return matchedCode;
208	    }
209	}
